-- Version reserved by scripts/new-migration.mjs against main and remote branches.
-- The 100-member roster tournament-fee boundary read timed out at 8s against
-- the original 3GB/2m-row source. Its old (club_id,player_id) index reads each
-- player's lifetime to test charged_at. Cover the unchanged exact time window.
-- Physical index only: no fee, money, row, function, ACL, source65 or GEN change.
-- Full roster cash win/loss and whole-response performance remain separate proof.
-- @live-proof: (SELECT indisvalid AND indisready AND indislive FROM pg_index WHERE indexrelid=to_regclass('public.accounting_tournament_member_charged_cover'))
CREATE INDEX CONCURRENTLY IF NOT EXISTS accounting_tournament_member_charged_cover
 ON public.accounting_tournament_fee_sources(club_id,player_id,charged_at) INCLUDE(rake_credit);
BEGIN;
SET LOCAL statement_timeout='5s';
SET LOCAL lock_timeout='1s';
DO $cover$DECLARE g text;seal text;triggers jsonb;BEGIN
 IF current_user<>'postgres'OR session_user<>'postgres'OR NULLIF(current_setting('request.jwt.claims',true),'')IS NOT NULL OR NULLIF(current_setting('request.jwt.claim.role',true),'')IS NOT NULL OR NULLIF(current_setting('request.jwt.claim.sub',true),'')IS NOT NULL OR NULLIF(current_setting('ca.break_window_migration_override',true),'')IS NOT NULL THEN RAISE EXCEPTION 'roster_tournament_fee_window_operator_refused';END IF;
 IF md5(pg_get_functiondef('public.ca_club_member_period_fee_totals(uuid,uuid[],date,timestamptz)'::regprocedure)) IS DISTINCT FROM '79889e997c09a52d8519b110bf0915b1' THEN RAISE EXCEPTION 'roster_tournament_fee_window_reader_changed';END IF;
 IF smarter_private.original_inventory_proof_sources_match()IS DISTINCT FROM true THEN RAISE EXCEPTION 'roster_tournament_fee_window_source65_required';END IF;
 SELECT jsonb_agg(to_jsonb(t)ORDER BY t.oid)INTO triggers FROM pg_trigger t WHERE t.tgrelid='public.accounting_tournament_fee_sources'::regclass;
 g:=smarter_private.original_inventory_basis_generation();seal:=pg_get_functiondef('smarter_private.original_inventory_proof_sources_match()'::regprocedure);IF g IS NULL THEN RAISE EXCEPTION 'roster_tournament_fee_window_generation_required';END IF;
 IF public.fn_ca_break_window_refuses_migrations(now())IS NOT NULL OR public.fn_platform_frozen()IS DISTINCT FROM false OR public.fn_active_maintenance_release_boundary()IS NOT NULL THEN RAISE EXCEPTION 'roster_tournament_fee_window_window_refused';END IF;
 IF NOT EXISTS(SELECT FROM pg_class c WHERE c.oid='public.accounting_tournament_fee_sources'::regclass AND c.relkind='r'AND c.relpersistence='p'AND c.relowner='postgres'::regrole AND c.relrowsecurity AND NOT c.relforcerowsecurity AND NOT EXISTS(SELECT FROM pg_policy p WHERE p.polrelid=c.oid) AND c.relacl::text='{postgres=arwdDxtm/postgres,service_role=r/postgres}')THEN RAISE EXCEPTION 'roster_tournament_fee_window_source_access_refused';END IF;
 IF(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid))ORDER BY a.attnum)FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.accounting_tournament_fee_sources'::regclass AND a.attnum>0 AND NOT a.attisdropped)IS DISTINCT FROM '[{"name":"id","type":"uuid","not_null":true,"default":"gen_random_uuid()"},{"name":"rake_record_id","type":"uuid","not_null":true,"default":null},{"name":"tournament_id","type":"uuid","not_null":true,"default":null},{"name":"player_id","type":"uuid","not_null":true,"default":null},{"name":"club_id","type":"uuid","not_null":true,"default":null},{"name":"union_id","type":"uuid","not_null":false,"default":null},{"name":"coordinator_union_id","type":"uuid","not_null":false,"default":null},{"name":"game_type","type":"text","not_null":true,"default":null},{"name":"registration_id","type":"uuid","not_null":true,"default":null},{"name":"source_charge_ledger_id","type":"uuid","not_null":true,"default":null},{"name":"source_entitlement_id","type":"uuid","not_null":true,"default":null},{"name":"charged_at","type":"timestamp with time zone","not_null":true,"default":null},{"name":"rake_credit","type":"numeric","not_null":true,"default":null},{"name":"contract","type":"jsonb","not_null":true,"default":null},{"name":"recorded_at","type":"timestamp with time zone","not_null":true,"default":"transaction_timestamp()"}]'::jsonb THEN RAISE EXCEPTION 'roster_tournament_fee_window_columns_refused';END IF;
 IF(SELECT jsonb_agg(jsonb_build_object('name',c.conname,'definition',pg_get_constraintdef(c.oid,true))ORDER BY c.conname)FROM pg_constraint c WHERE c.conrelid='public.accounting_tournament_fee_sources'::regclass)IS DISTINCT FROM '[{"name":"accounting_tournament_fee_sources_pkey","definition":"PRIMARY KEY (id)"},{"name":"accounting_tournament_fee_sources_rake_credit_check","definition":"CHECK (rake_credit >= 0::numeric AND rake_credit = round(rake_credit, 2) AND (rake_credit::text <> ALL (ARRAY[''NaN''::text, ''Infinity''::text, ''-Infinity''::text])))"},{"name":"accounting_tournament_fee_sources_rake_record_id_fkey","definition":"FOREIGN KEY (rake_record_id) REFERENCES accounting_tournament_fee_batches(rake_record_id)"},{"name":"accounting_tournament_fee_sources_rake_record_id_player_id_key","definition":"UNIQUE (rake_record_id, player_id)"},{"name":"accounting_tournament_fee_sources_source_entitlement_id_key","definition":"UNIQUE (source_entitlement_id)"}]'::jsonb THEN RAISE EXCEPTION 'roster_tournament_fee_window_constraints_refused';END IF;
 IF(SELECT jsonb_agg(pg_get_indexdef(i.indexrelid)ORDER BY pg_get_indexdef(i.indexrelid))FROM pg_index i WHERE i.indrelid='public.accounting_tournament_fee_sources'::regclass AND i.indexrelid<>to_regclass('public.accounting_tournament_member_charged_cover'))IS DISTINCT FROM '["CREATE INDEX accounting_tournament_fee_scope_union_cover ON public.accounting_tournament_fee_sources USING btree (tournament_id) INCLUDE (union_id)","CREATE INDEX accounting_tournament_fee_sources_club_event ON public.accounting_tournament_fee_sources USING btree (club_id, tournament_id)","CREATE INDEX accounting_tournament_fee_sources_club_recorded ON public.accounting_tournament_fee_sources USING btree (club_id, recorded_at) INCLUDE (charged_at)","CREATE INDEX accounting_tournament_fee_sources_coordinator_club ON public.accounting_tournament_fee_sources USING btree (coordinator_union_id, club_id) WHERE (coordinator_union_id IS NOT NULL)","CREATE INDEX accounting_tournament_fee_sources_coordinator_event ON public.accounting_tournament_fee_sources USING btree (coordinator_union_id, tournament_id) WHERE (coordinator_union_id IS NOT NULL)","CREATE INDEX accounting_tournament_fee_sources_event ON public.accounting_tournament_fee_sources USING btree (tournament_id, rake_record_id)","CREATE INDEX accounting_tournament_fee_sources_standalone_club ON public.accounting_tournament_fee_sources USING btree (club_id, tournament_id) WHERE (coordinator_union_id IS NULL)","CREATE INDEX accounting_tournament_rakeback_player ON public.accounting_tournament_fee_sources USING btree (club_id, player_id)","CREATE INDEX accounting_tournament_source_identity_keys_cover ON public.accounting_tournament_fee_sources USING btree (id) INCLUDE (tournament_id, rake_record_id)","CREATE INDEX accounting_tournament_source_record_credit_cover ON public.accounting_tournament_fee_sources USING btree (rake_record_id) INCLUDE (rake_credit)","CREATE INDEX accounting_tournament_standalone_club_event_cover ON public.accounting_tournament_fee_sources USING btree (club_id, tournament_id) INCLUDE (id, charged_at, rake_credit, union_id) WHERE (coordinator_union_id IS NULL)","CREATE INDEX accounting_tournament_week_club_event_cover ON public.accounting_tournament_fee_sources USING btree (coordinator_union_id, club_id, tournament_id) INCLUDE (id, charged_at, rake_credit, union_id) WHERE (coordinator_union_id IS NOT NULL)","CREATE UNIQUE INDEX accounting_tournament_fee_sources_pkey ON public.accounting_tournament_fee_sources USING btree (id)","CREATE UNIQUE INDEX accounting_tournament_fee_sources_rake_record_id_player_id_key ON public.accounting_tournament_fee_sources USING btree (rake_record_id, player_id)","CREATE UNIQUE INDEX accounting_tournament_fee_sources_source_entitlement_id_key ON public.accounting_tournament_fee_sources USING btree (source_entitlement_id)"]'::jsonb OR EXISTS(SELECT FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indrelid='public.accounting_tournament_fee_sources'::regclass AND i.indexrelid<>to_regclass('public.accounting_tournament_member_charged_cover')AND(NOT i.indisvalid OR NOT i.indisready OR NOT i.indislive OR c.relowner<>'postgres'::regrole))THEN RAISE EXCEPTION 'roster_tournament_fee_window_existing_indexes_refused';END IF;
 IF NOT EXISTS(SELECT FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_am am ON am.oid=c.relam WHERE i.indexrelid=to_regclass('public.accounting_tournament_member_charged_cover')AND i.indrelid='public.accounting_tournament_fee_sources'::regclass AND i.indisvalid AND i.indisready AND i.indislive AND NOT i.indisunique AND NOT i.indisprimary AND NOT i.indisexclusion AND i.indnkeyatts=3 AND i.indnatts=4 AND i.indexprs IS NULL AND i.indpred IS NULL AND c.relowner='postgres'::regrole AND c.relkind='i'AND c.relpersistence='p'AND am.amname='btree'AND pg_get_indexdef(i.indexrelid)='CREATE INDEX accounting_tournament_member_charged_cover ON public.accounting_tournament_fee_sources USING btree (club_id, player_id, charged_at) INCLUDE (rake_credit)')THEN RAISE EXCEPTION 'roster_tournament_fee_window_exact_catalog_required';END IF;
 IF(SELECT jsonb_agg(to_jsonb(t)ORDER BY t.oid)FROM pg_trigger t WHERE t.tgrelid='public.accounting_tournament_fee_sources'::regclass)IS DISTINCT FROM triggers THEN RAISE EXCEPTION 'roster_tournament_fee_window_original_triggers_changed';END IF;
 IF smarter_private.original_inventory_proof_sources_match()IS DISTINCT FROM true OR smarter_private.original_inventory_basis_generation()IS DISTINCT FROM g OR pg_get_functiondef('smarter_private.original_inventory_proof_sources_match()'::regprocedure)IS DISTINCT FROM seal THEN RAISE EXCEPTION 'roster_tournament_fee_window_original_source_changed';END IF;
END$cover$;
COMMIT;
